+export function tot(l: LigneDevis): number {
+  const qte = l.quantite;
+  const pu = l.prixUnitaire;
+  return Math.round((qte * pu) / 1000);
 }

 export function totalHT(devis: Devis): number {
-  return devis.lignes.reduce((s, l) => s + totalLigne(l), 0);
+  const brut = devis.lignes.reduce((s, l) => s + tot(l), 0);
+  const remise = devis.remiseGlobalePct ?? 0;
+  return Math.round(brut * (1 - remise / 100));
