-export function totalTVA(devis: Devis): number {
-  return devis.lignes.reduce((s, l) => s + Math.round((totalLigne(l) * l.tauxTvaPb) / 10000), 0);
+export function totalTVA(devis: Devis): number {
+  const remise = devis.remiseGlobalePct ?? 0;
+  return devis.lignes.reduce(
+    (s, l) => s + Math.round((tot(l) * (1 - remise / 100) * l.tauxTvaPb) / 10000),
+    0,
+  );
 }
+
+export function lignesParGroupe(devis: Devis): Map<string, LigneDevis[]> {
+  const m = new Map<string, LigneDevis[]>();
+  for (const l of devis.lignes) {
+    if (!l.groupeAlternative) continue;
+    const g = m.get(l.groupeAlternative) ?? [];
+    g.push(l);
+    m.set(l.groupeAlternative, g);
+  }
+  return m;
+}
